// The ball is moved first by step() and we only reveal collisions here, so
// the previous position (where the ball came from) is tracked to tell which
// face was hit: if the ball came from above/below the brick, it's a vertical
// hit (flip vy); if from the left/right, it's a horizontal hit (flip vx).
const prev = { x: state.ball.x - state.ball.vx * 1, y: state.ball.y - state.ball.vy * 1 };

// Bricks: collision + bounce + score + drawing, all in one place.
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  if (collides(state.ball, brick)) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Which face was hit? The ball entered the brick from the side that was
    // clear on the previous frame. Flip the velocity along that axis and push
    // the ball back out so it never tunnels through (fix for #1).
    const prevAbove = prev.y + state.ball.r <= brick.y;
    const prevBelow = prev.y - state.ball.r >= brick.y + brick.h;
    const prevLeft = prev.x + state.ball.r <= brick.x;
    const prevRight = prev.x - state.ball.r >= brick.x + brick.w;

    const hitVertical = prevAbove || prevBelow || Math.abs(state.ball.vy) >= Math.abs(state.ball.vx);
    if (hitVertical) {
      state.ball.vy = prevAbove ? Math.abs(state.ball.vy) : -Math.abs(state.ball.vy);
      state.ball.y = prevAbove ? brick.y - state.ball.r : brick.y + brick.h + state.ball.r;
    } else if (prevLeft || prevRight) {
      state.ball.vx = prevRight ? Math.abs(state.ball.vx) : -Math.abs(state.ball.vx);
      state.ball.x = prevRight ? brick.x + brick.w + state.ball.r : brick.x - state.ball.r;
    } else {
      // Fallback: hit a corner edge-on. Bounce on both axes.
      state.ball.vx = -state.ball.vx;
      state.ball.vy = -state.ball.vy;
    }
  }

