edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

test('frame: ball bouncing head-on off a brick is deflected upward, not destroyed', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // first (leftmost, topmost) live brick
  // Aim straight up into the bottom face of the brick.
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + state.ball.r + 2,
    r: BALL_R,
    vx: 0,
    vy: -300,
  };
  const before = state.ball.x;
  frame(ctxStub(), state);
  assert.equal(brick.alive, false, 'brick should be broken');
  assert.ok(state.ball.vy > 0, 'ball should now move downward (bounced off the brick bottom)');
  assert.ok(state.ball.y >= brick.y + brick.h + state.ball.r, 'ball should be pushed out below the brick');
  assert.equal(state.ball.vx, 0, 'horizontal velocity unchanged for a head-on hit');
  assert.equal(state.ball.x, before, 'x position unchanged for a head-on hit');
});

test('frame: ball hitting the side of a brick is deflected horizontally', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Approach the left face horizontally.
  state.ball = {
    x: brick.x - state.ball.r - 2,
    y: brick.y + brick.h / 2,
    r: BALL_R,
    vx: -300, // moving left, so it comes from the right side of the brick
    vy: 0,
  };
  frame(ctxStub(), state);
  assert.equal(brick.alive, false, 'brick should be broken');
  assert.ok(state.ball.vx > 0, 'ball should bounce to the right off the left face');
  assert.ok(state.ball.x >= brick.x + state.ball.r, 'ball should be pushed out right of the brick');
});

// Minimal no-op 2D context so frame() can run headless.
function ctxStub() {
  const noop = () => {};
  return {
    fillStyle: null,
    fillRect: noop,
    fillText: noop,
    beginPath: noop,
    arc: noop,
    fill: noop,
  };
}

