test('frame: ball hitting the bottom of a brick head-on bounces down, brick breaks', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball climbs straight up INTO the bottom face. Its current position overlaps
  // the brick; its previous position (one step back, moving up) was below it.
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h - 5, // pen�trates 5px through the bottom face
    r: BALL_R,
    vx: 0,
    vy: -300, // moving up; prev position is 15px below current
  };
  const before = state.ball.x;
  frame(ctxStub(), state);
  assert.equal(brick.alive, false, 'brick should be broken');
  assert.ok(state.ball.vy > 0, 'ball should bounce back down');
  assert.ok(state.ball.y > brick.y + brick.h - state.ball.r, 'ball pushed out below the brick');
  assert.equal(state.ball.vx, 0, 'head-on hit leaves horizontal velocity alone');
  assert.equal(state.ball.x, before, 'head-on hit leaves x alone');
});

test('frame: ball hitting the side of a brick bounces back horizontally', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Approaching from the right, moving left INTO the left face.
  state.ball = {
    x: brick.x + 5, // pen�trates 5px through the left face
    y: brick.y + brick.h / 2,
    r: BALL_R,
    vx: -300, // prev position is 80px right of current
    vy: 0,
  };
  frame(ctxStub(), state);
  assert.equal(brick.alive, false, 'brick should be broken');
  assert.ok(state.ball.vx > 0, 'ball should bounce back to the right');
  assert.ok(state.ball.x > brick.x - state.ball.r, 'ball pushed out right of the brick');
});

